    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

from itertools import product, combinations
import heapq


def _dependency_solver(preference, name_order):
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        ordered = names if name_order == "ascending" else list(reversed(names))
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]
        versions = {
            name: {row["version"]: row for row in rows}
            for name, rows in packages.items()
        }
        choices = []
        for name in names:
            available = [v for v in versions[name]
                         if v not in blocked.get(name, [])
                         and (name not in pins or pins[name] == v)]
            choices.append([-1] + available)

        best_vector = None
        best = None
        for values in product(*choices):
            installed = dict(zip(names, values))
            if any(installed.get(name, -1) < 0 or
                   not bounds[0] <= installed[name] <= bounds[1]
                   for name, bounds in roots.items()):
                continue

            edges = {name: [] for name, v in installed.items() if v >= 0}
            valid = True
            for name in edges:
                row = versions[name][installed[name]]
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    v = installed.get(other, -1)
                    if v < 0 or not dep["min"] <= v <= dep["max"]:
                        valid = False
                        break
                    edges[name].append(other)
                if not valid:
                    break
            if not valid:
                continue

            # Installed packages must be precisely the active closure of roots.
            reachable = set()
            stack = list(roots)
            while stack:
                name = stack.pop()
                if name in reachable:
                    continue
                reachable.add(name)
                stack.extend(edges.get(name, []))
            if reachable != set(edges):
                continue

            state, finished = set(), set()
            def acyclic(name):
                if name in state:
                    return False
                if name in finished:
                    return True
                state.add(name)
                if any(not acyclic(other) for other in edges[name]):
                    return False
                state.remove(name)
                finished.add(name)
                return True
            if not all(acyclic(name) for name in edges):
                continue

            vector = tuple(installed[n] for n in ordered)
            if best_vector is None or ((vector > best_vector) if preference == "maximum"
                                       else (vector < best_vector)):
                best_vector = vector
                best = {n: v for n, v in installed.items() if v >= 0}
        return {"versions": best} if best is not None else {"error": "unsatisfiable"}
    return solve


def _round(n, d, mode):
    return (n + d // 2) // d if mode == "half_up" else n // d


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        key = event.get("id", "anonymous:" + str(pos))
        rank = (event.get("revision", 0), pos)
        if key not in winners or rank > winners[key][0]:
            winners[key] = (rank, event)
    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), 10000, mode)
        tax = _round(raw * event.get("tax_bp", 0), 10000, mode)
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _quota_intervals(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    options = [j for j in jobs if j["id"] not in blocked]
    best_value = None
    best_ids = None
    for subset in combinations(options, k):
        ids = [j["id"] for j in subset]
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        events = []
        for j in subset:
            events.append((j["start"], 1))
            events.append((j["end"], -1))
        active = 0
        valid = True
        for _, delta in sorted(events, key=lambda x: (x[0], x[1])):
            active += delta
            if active > 2:
                valid = False
                break
        if not valid:
            continue
        value = sum(j["value"] for j in subset)
        sorted_ids = sorted(ids)
        if (best_value is None or value > best_value or
                (value == best_value and sorted_ids > best_ids)):
            best_value, best_ids = value, sorted_ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _temporal_routes(data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)
    source, target = data["source"], data["target"]
    initial_mask = bit.get(source, 0)
    initial = (source, initial_mask, data["coupons"])
    dist = {initial: data["start"]}
    queue = [(data["start"], source, initial_mask, data["coupons"])]
    while queue:
        arrival, node, mask, coupons = heapq.heappop(queue)
        state = (node, mask, coupons)
        if dist.get(state) != arrival:
            continue
        if node == target and mask == full:
            return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], coupons)]
            if coupons:
                duration = max(1, edge["duration"] - edge.get("discount", 0))
                choices.append((duration, coupons - 1))
            for duration, left in choices:
                new_time = depart + duration
                if new_time > data["deadline"]:
                    continue
                new_mask = mask | bit.get(edge["v"], 0)
                nxt = (edge["v"], new_mask, left)
                if new_time < dist.get(nxt, float("inf")):
                    dist[nxt] = new_time
                    heapq.heappush(queue, (new_time, *nxt))
    return {"arrival": None}


SOLVERS = {
    "component_01": _dependency_solver("maximum", "descending"),
    "component_02": _dependency_solver("minimum", "descending"),
    "component_03": _dependency_solver("maximum", "ascending"),
    "component_04": _dependency_solver("minimum", "ascending"),
    "component_05": _dependency_solver("maximum", "descending"),
    "component_06": _ledger,
    "component_07": _quota_intervals,
    "component_08": _temporal_routes,
}
